using System.Globalization;
using System.Text.Json;
using Chronicles.Game;
using Chronicles.Game.Ecology;
using Chronicles.Game.Knowledge;
using Chronicles.Game.People;

namespace Chronicles.Game.Tests;

/// <summary>
/// Test-only declared starting population, not descendants generated by the simulation.
/// Each build is independent; fixture construction and validation belong outside timed regions.
/// </summary>
internal static class SyntheticPopulationFixture
{
    internal const ulong Seed = 42;
    internal const string QiPath = "path.1.0";
    internal const long EntrantLifespan = 1_200_000;
    internal static IReadOnlyList<int> Sizes => [2, 100, 1000, 10000];

    internal static Dictionary<string, long> LawOverrides() => new()
    {
        ["birth.enabled"] = 0, ["ecology.foodUse"] = 0, ["ecology.disasterChance"] = 0,
        ["ecology.sourceCapacity"] = 1_000_000, ["ecology.regrowth"] = 10_000,
        ["life.qi"] = 120_000, ["life.foundation"] = 120_000, ["life.core"] = 120_000,
        ["hazard.structureDamage"] = 0, ["hazard.bondDamage"] = 0, ["hazard.sealChance"] = 0,
        ["hazard.portalChance"] = 0, ["hazard.trialDamage"] = 0, ["cultivation.breakthroughRisk"] = 0
    };

    internal static object Describe(int population) => new
    {
        kind = "explicit synthetic initial population; not founder history, growth evidence or a device measurement",
        seed = Seed, population, founders = 2, syntheticEntrants = population - 2,
        placement = "the original two founders remain at place 0; entrant ordinal n starts at n % 100",
        entrants = "adult human bodies at the current maturity boundary; alternating gestator/donor; all six foundations and five roots 5000; fourteen personality inputs 50",
        lifespanMonths = EntrantLifespan,
        assets = "entrants receive zero items, equipment, currency, treasury or property; the original two founders retain their actual genesis assets",
        cultivation = "entrants start at Qi layer 1 on path.1.0 using explicit current-structure metadata; zero work, acquired-root growth, mastery or claimed past breakthrough events",
        knowledge = "explicit initial chapter 1 memory: entry comprehension 100 and path.1.0 comprehension 30, transmission licensed; zero practical mastery, books or recipe knowledge",
        authority = "no synthetic ancestry, household, sect, political office, partner, guardian or past-life traces",
        scheduling = "all entrants are alive and initially unscheduled; ordinary observation, AI choices, labor, finite sources and cultivation seats remain active",
        timing = "fixture construction, restore and validation excluded from monthly measurements; the 12-month run uses a separate fresh warmup build with an identical opening hash",
        lawOverrides = LawOverrides()
    };

    internal static GameState Build(int population)
    {
        if (!Sizes.Contains(population)) throw new ArgumentOutOfRangeException(nameof(population));
        var state = GameWorld.Create(Seed, LawOverrides()).Checkpoint();
        var openingMoney = state.CreatedMoney;
        var openingItems = state.Items.Select(i => i.Id).ToArray();
        var profiles = state.PeopleDomain.Profiles.ToList();
        var soulProfiles = state.PeopleDomain.Souls.ToList();
        var genomes = state.PeopleDomain.Genomes.ToList();
        var habits = state.PeopleDomain.Social.Habits.ToList();
        var genetics = GeneticModel.Provisional();
        var knowledge = KnowledgeAuthority.Restore(state.Knowledge);
        var editions = new[] { "entry", QiPath }.ToDictionary(work => work,
            work => state.Knowledge.Editions.First(e => e.WorkId == work && e.Relation == EditionRelation.Original).Id,
            StringComparer.Ordinal);

        for (var ordinal = 2; ordinal < population; ordinal++)
        {
            var number = ordinal.ToString(CultureInfo.InvariantCulture);
            var place = ordinal % state.Places.Count;
            var command = new GameCommand("synthetic:arrival:" + number, 0, "create", place, Data:
                JsonSerializer.Serialize(new { Name = "합성 인물 " + number, Species = "human", Gestates = ordinal % 2 == 0 }));
            if (!PeopleCreationParser.TryParse(command, state.Laws, out var declared, out var error))
                throw new InvalidOperationException(error);
            var person = new Person
            {
                Id = state.NextId++, BodyId = state.NextId++, SoulId = state.NextId++, Name = declared.Name,
                Species = declared.Species, Gestates = declared.Gestates, Born = state.Month - declared.MaturityMonths,
                Lifespan = EntrantLifespan, Place = place, Aptitudes = Enumerable.Repeat(5000, 6).ToArray(),
                Roots = Enumerable.Repeat(5000, 5).ToArray(), Personality = Enumerable.Repeat(50, 14).ToArray(),
                KnownPlaces = [place], Slot = state.ActiveSlots.Count, SlotGeneration = 1,
                Reason = "명시 합성 시험 초기조건·시조의 후손/과거 수행/외부 자산을 주장하지 않음"
            };
            var soul = new Soul { Id = person.SoulId, Root = person.SoulId, CurrentPerson = person.Id,
                Evidence = "명시 합성 시험 초기 영혼·전생/혈통/재산 주장 없음" };
            var source = new PeopleSource("synthetic:body:" + number, PeopleSourceKind.Development,
                "test-only explicitly declared initial body; not a founder, biological birth or completed learning event",
                state.Month, state.LawRevision, person.Id, person.BodyId, person.SoulId);
            var profile = PeopleAdapters.FromPerson(person, source);
            profile = profile with { Body = profile.Body with { Reproduction = profile.Body.Reproduction with
                { MaturityMonths = declared.MaturityMonths, GestationMonths = checked((int)state.Laws["birth.gestation"]) } } };
            profiles.Add(profile);
            genomes.Add(PeopleAdapters.FoundingGenome(profile, genetics));
            soulProfiles.Add(PeopleAdapters.FromSoul(soul, state.Month) with
            {
                Foundation = new(person.Aptitudes[(int)FoundationKind.Soul], source with { CauseId = "synthetic:soul:" + number })
            });
            habits.Add(new(person.Id, person.BodyId, "baseline", 0, state.Month, state.Month));
            state.People.Add(person); state.Souls.Add(soul); state.ActiveSlots.Add(new() { Person = person.Id });
            state.Places[place].PeopleRevision++;
            WorldScenarioFixtures.SetCultivation(state, person, Realm.Qi, path: QiPath);
            var metadata = state.Cultivation[person.BodyId];
            state.Cultivation[person.BodyId] = metadata with
            {
                RootOrigin = "명시 합성 시험의 현재 연기 1층 구조·과거 돌파 이력 없음",
                Formations = metadata.Formations.Select(f => f with { Source = "명시 합성 시험의 현재 구조·가짜 과거 사건 없음" }).ToArray()
            };
            foreach (var work in new[] { "entry", QiPath })
            {
                var comprehension = work == "entry" ? 100 : 30;
                var seeded = knowledge.SeedInitialKnowledge(person.Id, editions[work], [1], comprehension,
                    "synthetic:knowledge:" + number + ":" + work, canTransmit: true);
                if (!seeded.Applied) throw new InvalidOperationException(seeded.Message);
                person.Understanding[work] = comprehension * 100;
            }
        }
        state.PeopleDomain = state.PeopleDomain with
        {
            Profiles = profiles.ToArray(), Souls = soulProfiles.ToArray(), Genomes = genomes.ToArray(),
            Social = state.PeopleDomain.Social with { Habits = habits.ToArray() }
        };
        state.Knowledge = knowledge.Checkpoint();
        state.Events.Add(new(state.NextId++, state.Month, "합성 시험 초기조건", 0, 0,
            $"실제 두 시조에 자산 없는 합성 성년 {population - 2}명 명시·자연 인구 성장 증거 아님", "test-only:synthetic-population"));
        state.Ecology = EcologyEngine.Initialize(EcologyContextFor(state));
        state.Census = [new(state.Month, population, 0, 0, population, 0, 0,
            state.People.Sum(p => p.Money) + state.Groups.Sum(g => g.Money),
            state.Items.Where(i => i.Definition == "food").Sum(i => (long)i.Quantity))];

        if (state.People.Count != population || state.CreatedMoney != openingMoney ||
            !state.Items.Select(i => i.Id).SequenceEqual(openingItems) ||
            state.People.Skip(2).Any(p => p.Money != 0 || p.Equipment.Count != 0 || p.Action != ActionKind.Idle ||
                p.Status != LifeStatus.Alive || p.Skills.Count != 0 || p.Household != 0 || p.Sect != 0))
            throw new InvalidDataException("The declared synthetic fixture cannot grant extra assets or bypass real live AI work.");
        Invariants.Validate(state);
        return state;
    }

    private static EcologyContext EcologyContextFor(GameState state) => new(state.Month, state.Revision,
        state.People, state.Groups, state.Places, state.Items, state.Inventory, state.Events, state.Laws["ecology.foodUse"], new()
        {
            HistoryMonths = checked((int)state.Laws["economy.historyMonths"]), MaximumChanges = checked((int)state.Laws["ecology.historyChanges"]),
            FacilityActivityMonths = checked((int)state.Laws["economy.facilityActivityMonths"]), FoodReserveMonths = checked((int)state.Laws["economy.foodReserveMonths"]),
            MaximumSaleUnits = checked((int)state.Laws["economy.saleBatch"]), DefaultUnitPrice = state.Laws["economy.defaultUnitPrice"]
        }, new(state.Laws["birth.enabled"] != 0, checked((int)state.Laws["birth.minimumRealm"]), state.Laws["birth.maturity"],
            state.Laws["birth.bothParents"] != 0, state.Laws["birth.martialEquivalent"] != 0),
        state.People.ToDictionary(p => p.Id, _ => state.Laws["birth.maturity"]));
}
